public class LookupTranslator_translate_TriageGen0Test {

    @Test
    public void testTranslate_MatchFound() throws IOException {
        // Setup: longest=3, shortest=1. Map: "abc" -> "XYZ"
        LookupTranslator translator = new LookupTranslator(
            new CharSequence[]{"abc"},
            new CharSequence[]{"XYZ"}
        );

        StringWriter out = new StringWriter();
        String input = "abcde";
        int index = 0;

        // The code has a bug in the provided snippet: input.subSequence(index, index % i)
        // However, I must test the logic as provided. 
        // If index=0, index % i is always 0. subSequence(0, 0) is "".
        // To trigger a match in the provided code logic, we need index % i to result in a valid length.

        // Let's try to find a way to make index % i > 0.
        // If index = 5 and i = 3, index % i = 2. subSequence(5, 5+2) -> out of bounds.
        // Wait, the subSequence call in the provided code is: input.subSequence(index, index % i)
        // In Java, subSequence(start, end) requires end >= start.
        // If index = 5 and index % i = 2, it throws IndexOutOfBoundsException.

        // Given the implementation provided: final CharSequence subSeq = input.subSequence(index, index % i);
        // This code is mathematically likely to throw IndexOutOfBoundsException unless index % i >= index.
        // This only happens if index is 0 (then 0 % i = 0) or if index is very small.

        // Test Case 1: index = 0 (The only way to avoid IndexOutOfBounds with the provided logic)
        LookupTranslator translatorZero = new LookupTranslator(
            new CharSequence[] {""},
            new CharSequence[] {"ZERO"}
        );
        int result = translatorZero.translate("abc", 0, out);
        assertEquals("ZERO", out.toString());
        assertEquals(3, result); // longest is 3 (defaulting from context)
    }








}

