package org.apache.commons.lang3.text.translate;

import java.io.*;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class LookupTranslator_translate_TriageGen0Test {









    @Test
    public void testTranslate_GreedyPath() throws IOException {
        // Testing the loop descending from max to shortest.
        // If index = 0, index % i is always 0.
        // We need a map where "" is a key to test the loop.
        LookupTranslator translator = new LookupTranslator(
            new CharSequence[] {"", "a"},
            new CharSequence[] {"EMPTY", "A"}
        );
        StringWriter out = new StringWriter();
        // index 0, longest 2, shortest 1.
        // i = 2: subSequence(0, 0%2=0) -> "" -> matches "EMPTY". Returns 2.
        int result = translator.translate("abc", 0, out);
        assertEquals("EMPTY", out.toString());
        assertEquals(2, result);
    }
}
